/* JAPRO - Corregedoria-Geral PMMT - pacote autoinstalável */
(function(){var H="<title>JAPRO Corregedoria-Geral</title>\n<meta name=\"claude:viewport-fit-sides\" content=\"cover\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Cinzel:wght@600;700&family=IBM+Plex+Sans:ital,wght@0,400;0,500;0,600;0,700;1,400&family=IBM+Plex+Mono:wght@400;500&family=Source+Serif+4:opsz,wght@8..60,400;8..60,600;8..60,700&display=swap\">\n<style>\n/* Layout: faixa institucional azul-marinho (padrão do portal PMMT) + abas + área de trabalho em 2 colunas que viram 1 no celular */\n:root{\n  --navy:#0f1d4d; --navy-2:#1c2f75; --steel:#2a5aa8; --gold:#b8922a; --gold-2:#d9b44a;\n  --bg:#eef1f7; --surface:#ffffff; --surface-2:#f6f8fc; --line:#d5dbe8; --ink:#141b33; --muted:#5b6582;\n  --ok:#1f7a4d; --warn:#a86b00; --bad:#b3261e; --info:#2a5aa8;\n  --ok-bg:#e6f4ec; --warn-bg:#fdf3e0; --bad-bg:#fbe9e7; --info-bg:#e8eefa;\n  --f-display:\"Cinzel\",\"Trajan Pro\",Georgia,serif;\n  --f-body:\"IBM Plex Sans\",-apple-system,\"Segoe UI\",Roboto,sans-serif;\n  --f-mono:\"IBM Plex Mono\",ui-monospace,Menlo,monospace;\n  --f-doc:\"Source Serif 4\",\"Times New Roman\",Georgia,serif;\n  --r:6px;\n}\n@media (prefers-color-scheme: dark){:root:not([data-theme=\"light\"]){\n  --bg:#0a1022; --surface:#121a33; --surface-2:#0f1730; --line:#26315a; --ink:#e6eaf6; --muted:#9aa6c8;\n  --ok:#5fcf95; --warn:#f0b84a; --bad:#ff8a80; --info:#8fb4ff; --steel:#6f9bff; --gold:#d9b44a;\n  --ok-bg:#12301f; --warn-bg:#33270f; --bad-bg:#3a1714; --info-bg:#16244a; --bad-fg:#2a0d0b; --tab-sel:#2a4a9a; color-scheme:dark}}\n:root[data-theme=\"dark\"]{\n  --bg:#0a1022; --surface:#121a33; --surface-2:#0f1730; --line:#26315a; --ink:#e6eaf6; --muted:#9aa6c8;\n  --ok:#5fcf95; --warn:#f0b84a; --bad:#ff8a80; --info:#8fb4ff; --steel:#6f9bff; --gold:#d9b44a;\n  --ok-bg:#12301f; --warn-bg:#33270f; --bad-bg:#3a1714; --info-bg:#16244a; --bad-fg:#2a0d0b; --tab-sel:#2a4a9a; color-scheme:dark}\n*{box-sizing:border-box}\n[hidden]{display:none!important}\nhtml,body{height:auto}\nbody{background:var(--bg);color:var(--ink);font-family:var(--f-body);font-size:15px;line-height:1.5}\nbody::before{content:\"\";position:fixed;inset:0 0 auto;height:env(safe-area-inset-top,0px);z-index:10;background:var(--navy)}\n.gut{padding-left:max(16px,env(safe-area-inset-left,0px));padding-right:max(16px,env(safe-area-inset-right,0px))}\n.wrap{max-width:1320px;margin:0 auto}\nheader.top{background:linear-gradient(180deg,var(--navy),#0b1640);color:#fff;border-bottom:3px solid var(--gold)}\n.top .wrap{display:flex;align-items:center;gap:16px;padding-block:14px;flex-wrap:wrap}\n.top img{width:64px;height:64px;border-radius:50%;box-shadow:0 0 0 2px rgba(217,180,74,.5)}\n.brand{display:flex;flex-direction:column;gap:2px;min-width:0}\n.brand .k{font-family:var(--f-display);letter-spacing:.14em;font-size:12px;color:var(--gold-2)}\n.brand h1{margin:0;font-family:var(--f-display);font-size:clamp(19px,2.6vw,26px);letter-spacing:.06em;font-weight:700;text-wrap:balance}\n.brand .s{font-size:12.5px;color:#c5cdea}\n.envpill{margin-left:auto;font-size:12px;border:1px solid rgba(255,255,255,.28);padding:5px 10px;border-radius:99px;color:#dfe5fa;display:flex;gap:8px;align-items:center}\n.envpill b{color:var(--gold-2);font-weight:600}\nnav.tabs{background:#d7dcea;border-bottom:1px solid var(--line);position:sticky;top:env(safe-area-inset-top,0px);z-index:5}\n:root[data-theme=\"dark\"] nav.tabs{background:#16204a}\n@media (prefers-color-scheme: dark){:root:not([data-theme=\"light\"]) nav.tabs{background:#16204a}}\nnav.tabs .wrap{display:flex;gap:2px;overflow-x:auto}\nnav.tabs button{all:unset;cursor:pointer;padding:12px 16px;font-size:12.5px;letter-spacing:.1em;text-transform:uppercase;font-weight:600;color:var(--navy-2);white-space:nowrap}\n:root[data-theme=\"dark\"] nav.tabs button{color:#c6d1f5}\n@media (prefers-color-scheme: dark){:root:not([data-theme=\"light\"]) nav.tabs button{color:#c6d1f5}}\nnav.tabs button[aria-selected=\"true\"]{background:var(--tab-sel,var(--steel));color:#fff}\nnav.tabs button:focus-visible{outline:2px solid var(--gold);outline-offset:-2px}\nmain{padding-block:22px 60px}\n.view[hidden]{display:none!important}\n.grid{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,1fr);gap:20px}\n@media (max-width:960px){.grid{grid-template-columns:minmax(0,1fr)}}\n.panel{background:var(--surface);border:1px solid var(--line);border-radius:var(--r);padding:18px;min-width:0}\n.panel h2{margin:0 0 4px;font-size:13px;letter-spacing:.12em;text-transform:uppercase;color:var(--steel);font-weight:700}\n.panel .lead{margin:0 0 14px;color:var(--muted);font-size:13.5px}\n.stack{display:flex;flex-direction:column;gap:14px}\n.row{display:flex;gap:10px;flex-wrap:wrap;align-items:center}\n.drop{border:2px dashed var(--line);border-radius:var(--r);padding:26px 16px;text-align:center;background:var(--surface-2);cursor:pointer;transition:border-color .15s}\n.drop.on{border-color:var(--steel);background:var(--info-bg)}\n.drop strong{display:block;font-size:15px}\n.drop span{color:var(--muted);font-size:13px}\n.btn{all:unset;box-sizing:border-box;cursor:pointer;display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:10px 16px;border-radius:var(--r);font-weight:600;font-size:13.5px;border:1px solid var(--line);background:var(--surface);color:var(--ink)}\n.btn:hover{border-color:var(--steel)}\n.btn:focus-visible{outline:2px solid var(--gold);outline-offset:2px}\n.btn.pri{background:var(--navy-2);border-color:var(--navy-2);color:#fff;letter-spacing:.06em;text-transform:uppercase;padding:12px 20px}\n.btn.pri:hover{background:var(--steel);border-color:var(--steel)}\n.btn.gold{background:var(--gold);border-color:var(--gold);color:#1a1300}\n.btn.danger{color:var(--bad);border-color:var(--bad)}\n.engcard .btn[disabled]{opacity:.45}\n.btn[disabled]{opacity:.45;pointer-events:none}\n.btn.sm{padding:6px 10px;font-size:12.5px}\n.files{display:flex;flex-direction:column;gap:10px}\n.file{position:relative;border:1px solid var(--line);border-radius:var(--r);padding:10px 44px 10px 12px;background:var(--surface-2)}\n.file .fx{position:absolute;top:6px;right:6px;width:32px;height:32px;border-radius:50%;border:1px solid var(--line);background:var(--surface);color:var(--muted);font-size:20px;line-height:1;cursor:pointer;display:grid;place-items:center}\n.file .fx:hover{color:var(--bad-fg,#fff);background:var(--bad);border-color:var(--bad)}\n.file .fx:disabled{opacity:.4;cursor:default}\n.file .nm{font-weight:600;word-break:break-all;font-size:13.5px}\n.file .meta{font-size:12.5px;color:var(--muted);font-family:var(--f-mono)}\n.bar{height:8px;background:var(--line);border-radius:99px;overflow:hidden;margin-top:6px}\n.bar>i{display:block;height:100%;width:0;background:linear-gradient(90deg,var(--steel),var(--gold));transition:width .2s}\n.big .bar{height:12px}\n/* barra em espera do modelo (pipeline.js barBusy): faixa indeterminada correndo sobre o trilho */\n.bar{position:relative}.bar.busy::after{content:\"\";position:absolute;top:0;bottom:0;left:-30%;width:30%;background:linear-gradient(90deg,transparent,rgba(255,255,255,.55),transparent);animation:barslide 1.4s linear infinite}\n.bar.busy>i{min-width:2%}\n@keyframes barslide{to{left:100%}}\n@media (prefers-reduced-motion:reduce){.bar.busy::after{animation:none;left:0;width:100%;opacity:.35}}\n/* reescrita do despacho (assemble.js redraftBusy): faixa sobre o documento antigo, esmaecido */\n.redraft-band{display:flex;flex-wrap:wrap;align-items:center;gap:4px 10px;border:1px solid var(--steel);border-left:6px solid var(--steel);background:var(--info-bg);border-radius:var(--r);padding:10px 14px;font-size:13.5px}\n.redraft-band span:last-child{flex-basis:100%;color:var(--muted);font-size:12.5px;padding-left:28px}\n.redraft-band .rb-spin{width:16px;height:16px;border-radius:50%;border:2px solid var(--steel);border-top-color:transparent;animation:spin 1s linear infinite;flex:none}\n.docprev.stale{opacity:.45;pointer-events:none;filter:grayscale(.4);transition:opacity .2s}\n.stages{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:8px}\n.stages li{display:grid;grid-template-columns:22px minmax(0,1fr) auto;gap:12px;align-items:start;padding:10px 12px;border-radius:var(--r);border:1px solid var(--line);background:var(--surface);font-size:13.5px}\n.stages li .d{width:18px;height:18px;border-radius:50%;border:2px solid var(--line);margin-top:2px;box-sizing:border-box}\n.stages li .sb{min-width:0;display:flex;flex-direction:column;gap:4px}\n.stages li .sh{display:flex;align-items:center;gap:8px;flex-wrap:wrap}\n.stages li .sh b{font-size:14px}\n.stages li .sst{font-size:10.5px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;padding:1px 8px;border-radius:999px;background:var(--surface-2);color:var(--muted);border:1px solid var(--line)}\n.stages li p{margin:0;font-size:12.5px;line-height:1.45;color:var(--muted);text-align:justify}\n.stages li .sl{font-weight:700;color:var(--ink)}\n.stages li .sr{color:var(--ink);background:var(--surface-2);border-left:3px solid var(--line);border-radius:6px;padding:5px 9px;text-align:left}\n.stages li.pend{opacity:.78}\n.stages li.run{border-color:var(--steel);background:var(--info-bg);opacity:1}\n.stages li.run .d{border-color:var(--steel);border-top-color:transparent;animation:spin 1s linear infinite}\n.stages li.run .sst{background:var(--steel);border-color:var(--steel);color:#fff}\n.stages li.run .sr{border-left-color:var(--steel);background:var(--surface)}\n.stages li.done .d{background:var(--ok);border-color:var(--ok)}\n.stages li.done .sst{background:var(--ok-bg);border-color:var(--ok);color:var(--ok)}\n.stages li.done .sr{border-left-color:var(--ok);background:var(--ok-bg)}\n.stages li.err{border-color:var(--bad);background:var(--bad-bg)}\n.stages li.err .d{background:var(--bad);border-color:var(--bad)}\n.stages li.err .sst{background:var(--bad);border-color:var(--bad);color:#fff}\n.stages li.err .sr{border-left-color:var(--bad);background:var(--surface)}\n.stages li small{display:block;color:var(--muted);font-size:12px}\n.stages li .t{font-family:var(--f-mono);font-size:12px;color:var(--muted);white-space:nowrap;padding-top:2px}\n@keyframes spin{to{transform:rotate(360deg)}}\n@media (prefers-reduced-motion:reduce){.stages li.run .d{animation:none}}\n.kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}\n@media (max-width:600px){.kpis{grid-template-columns:repeat(2,minmax(0,1fr))}}\n.kpi{display:flex;flex-direction:column;gap:4px;border:1px solid var(--line);border-top:3px solid var(--navy-2);border-radius:var(--r);padding:10px 12px 11px;background:var(--surface-2);min-width:0}\n.kpi .kl{font-size:10.5px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.04em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.kpi b{display:block;font-family:var(--f-body);font-size:clamp(17px,1.9vw,22px);font-weight:700;line-height:1.15;color:var(--ink);font-variant-numeric:tabular-nums;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100%}\n.kpi small{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.kpi small{display:block;font-size:11.5px;line-height:1.35;color:var(--muted);font-variant-numeric:tabular-nums}\n.kpi-eta.fim{border-top-color:var(--ok)}\n.kpi-eta.fim b{color:var(--ok)}\n.log{font-family:var(--f-mono);font-size:12px;background:var(--surface-2);border:1px solid var(--line);border-radius:var(--r);padding:10px;max-height:240px;overflow:auto;white-space:pre-wrap;word-break:break-word}\n.log .e{color:var(--bad)} .log .w{color:var(--warn)} .log .o{color:var(--ok)}\n.alert{border-radius:var(--r);padding:12px 14px;font-size:13.5px;border:1px solid}\n.alert.bad{background:var(--bad-bg);border-color:var(--bad);color:var(--ink)}\n.alert.warn{background:var(--warn-bg);border-color:var(--warn)}\n.alert.info{background:var(--info-bg);border-color:var(--info)}\n.alert.ok{background:var(--ok-bg);border-color:var(--ok)}\n.alert b{display:block;margin-bottom:2px}\n.verdict{display:grid;grid-template-columns:auto minmax(0,1fr);gap:16px;align-items:center;border:1px solid var(--line);border-left:4px solid var(--navy-2);border-radius:var(--r);padding:14px 16px;background:var(--surface)}\n.verdict .lab{font-size:11.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--muted)}\n.verdict .res{font-family:var(--f-display);font-size:clamp(18px,2.4vw,24px);font-weight:700;color:var(--navy-2)}\n:root[data-theme=\"dark\"] .verdict .res{color:#c6d1f5}\n@media (prefers-color-scheme: dark){:root:not([data-theme=\"light\"]) .verdict .res{color:#c6d1f5}}\n.verdict .num{display:flex;flex-direction:column;align-items:center;justify-content:center;width:58px;height:58px;border-radius:10px;background:var(--navy-2);color:#fff;font-family:var(--f-body);font-size:24px;font-weight:700;line-height:1}\n.verdict .num::before{content:\"Modelo\";font-size:9.5px;font-weight:600;letter-spacing:.08em;text-transform:uppercase;opacity:.8;margin-bottom:4px}\n:root[data-theme=\"dark\"] .verdict{border-left-color:var(--steel)}\n@media (prefers-color-scheme: dark){:root:not([data-theme=\"light\"]) .verdict{border-left-color:var(--steel)}}\n.chip{display:inline-flex;align-items:center;gap:6px;font-size:12px;padding:3px 9px;border-radius:99px;border:1px solid var(--line);background:var(--surface-2)}\n.chip.ok{border-color:var(--ok);color:var(--ok)} .chip.warn{border-color:var(--warn);color:var(--warn)} .chip.bad{border-color:var(--bad);color:var(--bad)}\n.chip.mem{border-color:var(--gold);color:var(--warn);background:var(--warn-bg);font-size:10.5px;padding:1px 7px;letter-spacing:.04em;text-transform:uppercase}\n/* Campos do despacho: grupos com título em maiúsculas pequenas (≥18px entre grupos); rótulo colado ao campo (4px), com o asterisco ou “opcional” na mesma linha */\n.fgroups{display:flex;flex-direction:column;gap:22px}\n.fgroup{display:flex;flex-direction:column;gap:8px}\n/* rótulos sempre em uma linha: campos lado a lado ficam na mesma altura */\n.fields label.f .lb{display:flex;align-items:center;flex-wrap:nowrap;gap:0;min-width:0;min-height:20px}\n.fields .lbt{flex:0 1 auto;min-width:0}\n.fields .lb>*:not(.lbt){flex:none}\n.fields .lb>.opt,.fields .lb>.req{margin-left:6px}\n.fields .lb .tipi{flex:none}\n.fields .f-wrap{align-self:end}\n.fields input:not([type=checkbox]),.fields select{height:42px;box-sizing:border-box}\n/* bloco \"Antes de iniciar\" dentro do quadro 1, logo acima do botão Iniciar */\n.prestart{margin:14px 0 4px;padding:14px 16px 12px;border:1px solid var(--line);border-left:4px solid var(--gold-2);border-radius:var(--r);background:var(--surface-2);transition:box-shadow .3s,border-color .3s}\n.prestart .ps-head{display:flex;align-items:flex-start;gap:12px;margin-bottom:10px}\n.prestart .ps-head b{display:block;font-size:14px;color:var(--ink)}\n.prestart .ps-sub{display:block;font-size:12.5px;color:var(--muted);margin-top:2px}\n.ps-step{flex:0 0 26px;height:26px;border-radius:50%;background:var(--gold-2);color:#1b1404;font-weight:700;display:flex;align-items:center;justify-content:center;font-size:13px}\n.prestart.done .ps-step{background:var(--ok);color:#fff}\n.prestart.done{border-left-color:var(--ok)}\n.ps-inline{display:inline-flex;width:24px;height:24px;flex:none;margin-right:10px;vertical-align:middle;font-size:12.5px}\n.start-hint{color:var(--warn);font-weight:600;margin:8px 0 0}\n/* dica ao passar o mouse (ou tocar) no \"?\" ao lado do rótulo */\n.tipi{position:relative;display:inline-flex;align-items:center;justify-content:center;width:16px;height:16px;margin-left:6px;border-radius:50%;background:var(--info-bg);color:var(--steel);border:1px solid var(--steel);font-size:10.5px;font-weight:700;font-style:normal;cursor:help;vertical-align:1px;outline:none}\n.tipi:hover,.tipi:focus{background:var(--steel);color:#fff}\n.tipbox{position:absolute;left:-12px;bottom:calc(100% + 10px);width:280px;max-width:80vw;display:flex;flex-direction:column;gap:8px;padding:12px 14px;border-radius:8px;background:#141b33;color:#eef1f7;text-align:left;font:400 12.5px/1.5 var(--f-body);letter-spacing:0;text-transform:none;font-variant:normal;white-space:normal;box-shadow:0 10px 28px rgba(0,0,0,.28);opacity:0;visibility:hidden;transform:translateY(4px);transition:opacity .15s,transform .15s;z-index:60;pointer-events:none}\n.tipbox:after{content:\"\";position:absolute;left:14px;top:100%;border:6px solid transparent;border-top-color:#141b33}\n.tipbox .tx{display:flex;flex-direction:column;gap:2px;padding-top:8px;border-top:1px solid rgba(255,255,255,.14);font-family:var(--f-mono);font-size:12px;color:#f3dc95;word-break:break-word}\n.tipbox .tx b{font-family:var(--f-body);font-size:10.5px;letter-spacing:.08em;text-transform:uppercase;color:#9fb0e0;font-weight:600}\n.tipi:hover .tipbox,.tipi:focus .tipbox{opacity:1;visibility:visible;transform:none}\n.tipi.flip .tipbox{left:auto;right:-12px}.tipi.flip .tipbox:after{left:auto;right:14px}\n.ps-ok{margin-left:auto;font-size:12px;font-weight:600;color:var(--ok);white-space:nowrap}\n.prestart .fg-title,.prestart .fg-lead{display:none}\n.prestart.attn{border-color:var(--warn);box-shadow:0 0 0 3px rgba(217,180,74,.35);animation:psPulse 1s ease 2}\n.ps-msg{margin:10px 0 0;font-size:13px;color:var(--warn);font-weight:600}\n@keyframes psPulse{50%{box-shadow:0 0 0 7px rgba(217,180,74,.15)}}\n\n.fg-title{margin:0;font-size:11.5px;letter-spacing:.12em;text-transform:uppercase;font-variant:small-caps;color:var(--steel);font-weight:700;padding-bottom:4px;border-bottom:1px solid var(--line)}\n.fg-lead{margin:0;font-size:12.5px;color:var(--muted)}\n.fields{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px 14px}\n@media (max-width:640px){.fields{grid-template-columns:minmax(0,1fr)}}\n.fields .full{grid-column:1/-1}\n.f-wrap{display:flex;flex-direction:column;gap:4px;min-width:0}\n.f-wrap.off label.f input{opacity:.55}\nlabel.f{display:flex;flex-direction:column;gap:4px;font-size:12.5px;color:var(--muted);font-weight:500}\nlabel.f .lb{display:flex;align-items:baseline;gap:6px;flex-wrap:wrap;line-height:1.2}\n.opt{color:var(--muted);font-style:italic;font-weight:400;font-size:11.5px}\nlabel.chk{display:flex;align-items:center;gap:8px;font-size:12.5px;color:var(--ink);cursor:pointer;margin-top:2px}\nlabel.chk input{width:16px;height:16px;margin:0;accent-color:var(--navy-2)}\n.hint.warn{color:var(--warn)}\n.chkrow{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-top:-4px}\n.chkrow label.chk{margin:0;white-space:nowrap}\n.chkrow .hint.warn{font-size:12.5px;line-height:1.35;padding:4px 10px;border-left:3px solid var(--warn);background:var(--warn-bg);border-radius:4px}\nlabel.f input,label.f select,label.f textarea{font:inherit;font-size:14px;color:var(--ink);background:var(--surface-2);border:1px solid var(--line);border-radius:var(--r);padding:8px 10px;width:100%}\nlabel.f textarea{min-height:120px;resize:vertical}\nlabel.f input:focus,label.f select:focus,label.f textarea:focus{outline:2px solid var(--steel);outline-offset:-1px}\n.req{color:var(--bad)}\nlabel.f input.invalid{border-color:var(--bad);outline:1px solid var(--bad)}\n.hint.bad{color:var(--bad)}\n.docprev{background:#fff;color:#111;overflow-x:auto;font-family:var(--f-doc);font-size:14.5px;line-height:1.6;border:1px solid var(--line);border-radius:4px;padding:34px clamp(16px,5vw,56px);max-height:720px;overflow:auto;box-shadow:0 1px 0 rgba(0,0,0,.04)}\n.docprev .hd{text-align:center;font-weight:700;font-size:13px;line-height:1.35;letter-spacing:.02em;margin-bottom:18px}\n.docprev .hd img{width:62px;display:block;margin:0 auto 6px}\n.docprev h3{font-size:14.5px;margin:18px 0 6px;text-transform:uppercase}\n.docprev h4{font-size:14px;margin:14px 0 4px}\n.docprev p{text-align:justify;margin:0 0 9px;text-indent:2.2em}\n.docprev p.ni{text-indent:0}\n.docprev .ttl{text-align:center;font-weight:700;font-size:15px;margin:10px 0 12px;text-decoration:underline}\n.docprev table{border-collapse:collapse;width:100%;font-size:12.5px;margin:8px 0 12px}\n@media (max-width:640px){.docprev table{min-width:560px}.docprev{padding:20px 14px}}\n.modal .box .row a.btn{text-decoration:none}\n.docprev td,.docprev th{border:1px solid #666;padding:4px 6px;vertical-align:top;text-align:left}\n.docprev th{background:#e7ebf4}\n.docprev .sig{text-align:center;margin-top:30px}\n.docprev .dt{text-align:right;margin:20px 0}\n.docprev .ref{font-family:var(--f-mono);font-size:11.5px;color:#1c2f75;background:#eef2fb;padding:0 4px;border-radius:3px;white-space:nowrap}\n.docprev .flag{background:#fff0c2}\n.docprev ul{margin:0 0 10px 1.2em;padding:0}\n.docprev li{text-align:justify;margin-bottom:4px}\n.seg{display:inline-flex;border:1px solid var(--line);border-radius:var(--r);overflow:hidden}\n.seg button{all:unset;cursor:pointer;padding:7px 12px;font-size:12.5px;font-weight:600}\n.seg button[aria-pressed=\"true\"]{background:var(--navy-2);color:#fff}\n.eng{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}\n@media (max-width:760px){.eng{grid-template-columns:minmax(0,1fr)}}\n.apoio-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:16px;margin-top:6px}\n.apoio-card{border:1px solid var(--line);border-radius:var(--r);padding:18px 18px 16px;background:var(--surface-2);display:flex;flex-direction:column;gap:8px;position:relative}\n.apoio-card h3{margin:0;font-size:17px;color:var(--ink)}\n.apoio-ico{line-height:0;height:40px}.apoio-ico svg{display:block}\n.apoio-sub{margin:0;color:var(--muted);font-size:13px}\n.apoio-list{margin:6px 0 10px;display:flex;flex-direction:column;gap:10px}\n.ap-item{border-top:1px solid var(--line);padding-top:9px}\n.ap-k{display:block;font-size:11px;font-weight:700;letter-spacing:.07em;text-transform:uppercase;color:var(--navy-2);margin-bottom:3px}\n:root[data-theme=\"dark\"] .ap-k{color:#c6d1f5}\n@media (prefers-color-scheme: dark){:root:not([data-theme=\"light\"]) .ap-k{color:#c6d1f5}}\n.ap-item p{margin:0;font-size:13.5px;line-height:1.5;text-align:justify;hyphens:manual}\n.apoio-btn{margin-top:auto;display:flex;align-items:center;justify-content:center;height:52px;padding:0 18px;white-space:nowrap;text-decoration:none;text-transform:uppercase;letter-spacing:.06em;font-weight:600;font-size:13px;box-sizing:border-box;width:100%}\n.normtbl.gaps td:first-child{white-space:nowrap}\n.lgsearch{display:flex;gap:8px;flex-wrap:wrap;margin:10px 0}.lgsearch input{flex:1;min-width:220px}\n.lgrev{display:inline-block;font-size:11px;font-weight:700;letter-spacing:.06em;padding:1px 6px;border-radius:4px;background:var(--warn-bg);color:var(--bad);margin-left:6px}\n.lgtxt{white-space:pre-wrap;font-size:12.5px;margin:6px 0 0}.normtbl details summary{cursor:pointer;color:var(--muted)}\n.apoio-wa{background:#1DAA55;border-color:#1DAA55;color:#fff}.apoio-wa:hover{background:#178a45;border-color:#178a45}\n.engcard{border:1px solid var(--line);border-radius:var(--r);padding:14px;background:var(--surface-2);display:flex;flex-direction:column;gap:8px}\n.engcard.sel{border-color:var(--gold);box-shadow:0 0 0 1px var(--gold)}\n.engcard h3{margin:0;font-size:15px}\n.engcard p{margin:0;font-size:12.5px;color:var(--muted)}\n.flowbox{position:relative;height:min(72vh,720px);border:1px solid var(--line);border-radius:var(--r);overflow:hidden;background:var(--surface-2);touch-action:none;cursor:grab}\n.flowbox.drag{cursor:grabbing}\n.flowbox .tools{position:absolute;left:12px;bottom:12px;display:flex;flex-direction:column;gap:6px;z-index:2}\n.flowbox .tools .btn{width:38px;height:38px;padding:0;font-size:18px}\n.flowbox svg{position:absolute;inset:0;width:100%;height:100%}\n.md h3{font-family:var(--f-doc);font-size:17px;margin:18px 0 6px;color:var(--navy-2)}\n:root[data-theme=\"dark\"] .md h3{color:var(--gold-2)}\n@media (prefers-color-scheme: dark){:root:not([data-theme=\"light\"]) .md h3{color:var(--gold-2)}}\n.md p,.md li{max-width:72ch;text-align:justify}\n.md table{border-collapse:collapse;font-size:13.5px}\n.md td{border:1px solid var(--line);padding:5px 10px}\n.normtbl{width:100%;border-collapse:collapse;font-size:13px}\n.normtbl td,.normtbl th{border-bottom:1px solid var(--line);padding:8px;text-align:left;vertical-align:top}\n.normtbl th{font-size:11.5px;letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}\n.normtbl code{font-family:var(--f-mono);font-size:12px;color:var(--steel)}\n.scroll-x{overflow-x:auto}\n.hint{font-size:12.5px;color:var(--muted)}\n.foot{color:var(--muted);font-size:12px;text-align:center;padding-block:24px}\n/* avisos flutuantes (ui.js toast) */\n#toasts{position:fixed;right:max(16px,env(safe-area-inset-right,0px));bottom:calc(16px + env(safe-area-inset-bottom,0px));z-index:40;display:flex;flex-direction:column;align-items:flex-end;gap:8px;width:min(420px,calc(100vw - 32px));pointer-events:none}\n/* com um modal aberto, os avisos sobem para o topo e não capturam o clique: nunca cobrem os botões (Baixar, Li e vou conferir) */\nbody:has(#modal .modal) #toasts{bottom:auto;top:calc(12px + env(safe-area-inset-top,0px));z-index:60}\nbody:has(#modal .modal) #toasts .toast{pointer-events:none;opacity:.96}\nbody:has(#modal .modal) #toasts .toast .t-x{pointer-events:auto}\n.toast{pointer-events:auto;display:grid;grid-template-columns:24px 1fr 24px;gap:10px;align-items:start;width:100%;box-sizing:border-box;padding:11px 10px 11px 12px;border-radius:8px;background:var(--surface);color:var(--ink);border:1px solid var(--line);border-left:5px solid var(--info);box-shadow:0 8px 28px rgba(5,10,30,.22);font-size:13.5px;line-height:1.4;animation:tIn .18s ease-out}\n.toast .t-ico{width:24px;height:24px;border-radius:50%;display:grid;place-items:center;font-weight:700;font-size:13px;color:#fff;background:var(--info)}\n.toast .t-txt{display:flex;flex-direction:column;gap:2px;min-width:0}\n.toast .t-txt b{font-size:13.5px}\n.toast .t-txt span{overflow-wrap:anywhere;white-space:normal}\n.toast .t-x{border:0;background:transparent;color:var(--muted);font-size:18px;line-height:1;cursor:pointer;padding:2px;border-radius:4px}\n.toast .t-x:hover,.toast .t-x:focus-visible{color:var(--ink);background:var(--surface-2)}\n.toast.t-ok{border-left-color:var(--ok)}.toast.t-ok .t-ico{background:var(--ok)}\n.toast.t-warn{border-left-color:var(--warn)}.toast.t-warn .t-ico{background:var(--warn)}\n.toast.t-bad{border-left-color:var(--bad);background:var(--bad-bg)}.toast.t-bad .t-ico{background:var(--bad)}.toast.t-bad .t-txt b{color:var(--bad)}\n@keyframes tIn{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}\n@media (prefers-reduced-motion:reduce){.toast{animation:none}}\n/* painel de alertas antes de assinar (alerts.js alertasPainelHTML): resolver (vermelho) · conferir (âmbar) · ajustes automáticos (cinza, recolhidos) */\n.alp{border:1px solid var(--line);border-radius:var(--r);background:var(--surface);display:flex;flex-direction:column;overflow:hidden}\n.alp-h{padding:10px 14px;background:var(--surface-2);border-bottom:1px solid var(--line);font-size:14px}\n.alp-s{padding:10px 14px 4px;border-left:5px solid transparent}\n.alp-s+.alp-s{border-top:1px solid var(--line)}\n.alp-s h4,.alp-s summary{margin:0 0 6px;font-size:14px;font-weight:700;display:flex;align-items:center;gap:8px}\n.alp-acao{border-left-color:var(--bad);background:var(--bad-bg)}.alp-acao h4{color:var(--bad)}\n.alp-conferir{border-left-color:var(--warn);background:var(--warn-bg)}.alp-conferir h4{color:var(--warn)}\n.alp-info{border-left-color:var(--muted)}.alp-info summary{color:var(--muted);cursor:pointer;list-style:none;padding-bottom:6px}.alp-info summary::-webkit-details-marker{display:none}\n.alp-info[open] summary .alp-ver{display:none}.alp-ver{font-weight:400;text-decoration:underline}\n.alp-i{flex:0 0 auto;width:20px;height:20px;border-radius:50%;display:grid;place-items:center;font-size:12px;font-weight:700;color:#fff;background:var(--muted)}\n.alp-acao .alp-i{background:var(--bad)}.alp-conferir .alp-i{background:var(--warn)}\n.alp-l{margin:0 0 6px;padding-left:20px;display:flex;flex-direction:column;gap:8px;font-size:13.5px;line-height:1.45}\n.alp-it::marker{font-weight:700;color:var(--muted)}\n.alp-t{color:var(--ink)}.alp-f,.alp-imp{margin-top:2px}.alp-imp{color:var(--muted)}\n.alp-pgs{display:flex;flex-wrap:wrap;gap:4px;margin-top:4px}\n.alp-pg{font-family:var(--f-mono);font-size:11.5px;border:1px solid var(--line);background:var(--surface);border-radius:99px;padding:0 7px;color:var(--muted)}\n/* campos obrigatórios faltando (ui.js camposMarca) */\n.f-wrap.f-miss input,.f-wrap.f-miss select{border-color:var(--bad)!important;box-shadow:0 0 0 2px var(--bad-bg)}\n.f-wrap.f-miss .lb{color:var(--bad)}\n/* card fixo do encarregado incompatível (ui.js encCardUpdate) */\n.enc-card{border:1px solid var(--bad);border-left:6px solid var(--bad);background:var(--bad-bg);border-radius:var(--r);padding:12px 14px;display:flex;flex-direction:column;gap:6px}\n.enc-card .enc-t{color:var(--bad);font-size:15px}\n.enc-card p{margin:0;line-height:1.45;font-size:13.5px}\n.enc-card .enc-d{color:var(--muted);font-size:12.5px}\n.enc-card .enc-a{font-size:13px}\n.enc-card .row{margin-top:4px}\n.btn.danger-fill{background:var(--bad);border-color:var(--bad);color:var(--bad-fg,#fff)}\n#p-proc{scroll-margin-top:56px}\n.modal{position:fixed;inset:0;background:rgba(5,10,30,.55);display:flex;align-items:center;justify-content:center;z-index:20;padding:16px}\n.modal .box{background:var(--surface);border:1px solid var(--line);border-radius:var(--r);max-width:560px;width:100%;padding:20px;max-height:90vh;overflow:auto}\n.mic.on{background:var(--bad);border-color:var(--bad);color:#fff}\ndetails.acc{border:1px solid var(--line);border-radius:var(--r);background:var(--surface-2)}\ndetails.acc summary{cursor:pointer;padding:10px 12px;font-weight:600;font-size:13.5px}\ndetails.acc>div{padding:0 12px 12px}\n\n/* downloads: um grupo por documento, PDF e Word lado a lado com ícones próprios */\n.dl-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:12px}\n.dl-group{border:1px solid var(--line);border-radius:var(--r);background:var(--surface-2);padding:10px 12px 12px}\n.dl-group:not(:has(.dlb:not([hidden]))){display:none}\n.dl-gt{font-size:11.5px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--navy-2);margin-bottom:8px}\n:root[data-theme=\"dark\"] .dl-gt{color:#c6d1f5}\n@media (prefers-color-scheme: dark){:root:not([data-theme=\"light\"]) .dl-gt{color:#c6d1f5}}\n.dl-btns{display:grid;grid-template-columns:1fr 1fr;gap:8px}\n.btn.dlb{justify-content:flex-start;gap:10px;padding:8px 12px;min-height:52px;text-align:left;background:var(--surface)}\n.btn.dlb:hover{border-color:var(--navy-2);box-shadow:0 1px 0 var(--navy-2)}\n.btn.dlb .fi{flex:0 0 auto}\n.dlb-t{display:flex;flex-direction:column;line-height:1.15;min-width:0}\n.dlb-t b{font-size:14px}\n.dlb-t small{font-size:11.5px;font-weight:500;color:var(--muted)}\n.btn.dlb[aria-busy=\"true\"] .fi{opacity:.4}\n@media (max-width:420px){.dl-btns{grid-template-columns:1fr}}\n/* botão secundário de destaque (antigo dourado): segue a paleta azul da ferramenta */\n.btn.gold{background:var(--info-bg);border-color:var(--navy-2);color:var(--navy-2)}\n.btn.gold:hover{background:var(--navy-2);color:#fff}\n:root[data-theme=\"dark\"] .btn.gold{color:#c6d1f5;border-color:var(--steel)}\n@media (prefers-color-scheme: dark){:root:not([data-theme=\"light\"]) .btn.gold{color:#c6d1f5;border-color:var(--steel)}}\n\n/* aba Como usar (vídeos) */\n@media (max-width:760px){.vid-grid{grid-template-columns:1fr!important}}\n.vid-info{border:1px solid var(--line);border-left:4px solid var(--navy-2);border-radius:var(--r);background:var(--info-bg);padding:10px 14px;font-size:13.5px;line-height:1.5;text-align:justify}\n.vid-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px;margin-top:4px}\n.vid-card{border:1px solid var(--line);border-top:3px solid var(--navy-2);border-radius:var(--r);padding:16px 18px;background:var(--surface-2);display:flex;flex-direction:column;gap:8px}\n.vid-head{display:flex;align-items:center;gap:10px}\n.vid-head h3{margin:0;font-size:16.5px;color:var(--ink);line-height:1.25}\n.vid-num{flex:0 0 auto;width:28px;height:28px;border-radius:50%;background:var(--navy-2);color:#fff;font-weight:700;font-size:14px;display:grid;place-items:center}\n.vid-sub{margin:0;color:var(--muted);font-size:13px}\n.vid-k{font-size:11px;font-weight:700;letter-spacing:.07em;text-transform:uppercase;color:var(--navy-2);border-top:1px solid var(--line);padding-top:8px}\n:root[data-theme=\"dark\"] .vid-k{color:#c6d1f5}\n@media (prefers-color-scheme: dark){:root:not([data-theme=\"light\"]) .vid-k{color:#c6d1f5}}\n.vid-list{margin:0 0 6px;padding-left:18px;font-size:13.5px;line-height:1.5}\n.vid-list li{margin:0 0 4px}\n.btn.vid-btn{margin-top:auto;justify-content:flex-start;gap:10px;min-height:52px;padding:8px 14px;text-decoration:none;text-transform:uppercase;letter-spacing:.04em;font-size:12.5px;background:var(--surface);border-color:var(--navy-2);color:var(--navy-2);text-align:left}\n.btn.vid-btn:hover{background:var(--navy-2);color:#fff}\n.btn.vid-btn .yt-ico{flex:0 0 auto}\n.btn.vid-btn .vid-ext{margin-left:auto}\n:root[data-theme=\"dark\"] .btn.vid-btn{color:#c6d1f5;border-color:var(--steel)}\n@media (prefers-color-scheme: dark){:root:not([data-theme=\"light\"]) .btn.vid-btn{color:#c6d1f5;border-color:var(--steel)}}\n/* rodada 25: estado fixo do passo 1 do apensamento forçado, campo e botão do passo 2 realçados, destaque do cartão do resultado */\n.fz-status{display:flex;align-items:flex-start;gap:10px;border:1px solid var(--steel);border-left:6px solid var(--steel);background:var(--info-bg);border-radius:var(--r);padding:10px 12px;font-size:14px}\n.fz-status[hidden]{display:none}\n.fz-status .fz-ic{flex:none;width:18px;height:18px;margin-top:2px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-weight:700;font-size:12px}\n.fz-status.run .fz-ic{border:2px solid var(--steel);border-top-color:transparent;animation:spin 1s linear infinite}\n.fz-status.ok{border-color:var(--ok);border-left-color:var(--ok);background:var(--ok-bg)}.fz-status.ok .fz-ic{background:var(--ok);color:#06210f}\n.fz-status.bad{border-color:var(--bad);border-left-color:var(--bad);background:var(--bad-bg)}.fz-status.bad .fz-ic{background:var(--bad);color:#2a0d0b}\n.fz-status .fz-tx{flex:1}.fz-status .fz-tx b{display:block;margin-bottom:2px}.fz-status .fz-el{color:var(--muted);font-size:12.5px;margin-top:4px;display:block}\n.fz-status .fz-bar{display:block;height:4px;margin-top:6px;border-radius:2px;overflow:hidden;background:var(--line);position:relative}\n.fz-status .fz-bar::after{content:\"\";position:absolute;top:0;left:-40%;width:40%;height:100%;background:linear-gradient(90deg,var(--steel),var(--gold));animation:barslide 1.4s linear infinite}\n.fz-status .fz-x{flex:none;background:none;border:0;font-size:18px;line-height:1;cursor:pointer;color:inherit;padding:0 2px}\ntextarea.fz-hl{outline:3px solid var(--gold-2);outline-offset:2px;box-shadow:0 0 0 6px rgba(217,180,74,.18)}\n.btn.fz-go{box-shadow:0 0 0 0 rgba(217,180,74,.6);animation:psPulse 1.6s ease-in-out infinite;outline:2px solid var(--gold-2);outline-offset:2px}\n.verdict.res-flash{animation:resFlash 2.4s ease-out 1}\n@keyframes resFlash{0%,35%{box-shadow:0 0 0 4px var(--gold-2);background:var(--warn-bg)}100%{box-shadow:0 0 0 0 transparent}}\n@media (prefers-reduced-motion:reduce){.btn.fz-go,.fz-status.run .fz-ic,.fz-status .fz-bar::after,.verdict.res-flash{animation:none}}\n</style>\n\n<header class=\"top gut\"><div class=\"wrap\">\n  <img id=\"logo\" alt=\"Brasão da Corregedoria-Geral da PMMT\">\n  <div class=\"brand\">\n    <span class=\"k\">POLÍCIA MILITAR DO ESTADO DE MATO GROSSO · CORREGEDORIA-GERAL</span>\n    <h1>JAPRO · Juízo de Admissibilidade Processual</h1>\n    <span class=\"s\">Filtro de Admissibilidade da Denúncia · Matriz da Autoridade de Polícia Judiciária Militar</span>\n  </div>\n  <div class=\"envpill\" id=\"envpill\">Motor: <b id=\"envname\">detectando…</b></div>\n</div></header>\n\n<nav class=\"tabs gut\" aria-label=\"Seções\"><div class=\"wrap\" role=\"tablist\">\n  <button role=\"tab\" aria-selected=\"false\" data-v=\"apresentacao\">Apresentação</button>\n  <button role=\"tab\" aria-selected=\"false\" data-v=\"fluxo\">Fluxograma</button>\n  <button role=\"tab\" aria-selected=\"true\" data-v=\"analise\">Análise</button>\n  <button role=\"tab\" aria-selected=\"false\" data-v=\"normas\">Base normativa</button>\n  <button role=\"tab\" aria-selected=\"false\" data-v=\"videos\">Como usar</button>\n  <button role=\"tab\" aria-selected=\"false\" data-v=\"apoio\">Outras ferramentas de apoio</button>\n  <button role=\"tab\" aria-selected=\"false\" data-v=\"config\">Motores de IA</button>\n</div></nav>\n\n<main class=\"gut\"><div class=\"wrap\">\n\n<!-- ============ ANÁLISE ============ -->\n<section class=\"view\" id=\"v-analise\">\n  <div class=\"grid\">\n    <div class=\"stack\">\n      <div class=\"panel\" id=\"p-entrada\">\n        <h2>1 · Recepção do expediente</h2>\n        <p class=\"lead\">Carregue o processo completo (PDF, DOCX, TXT ou imagens). Pode ser mais de um arquivo: o sistema mantém a numeração de páginas de cada um. A leitura é feita no seu navegador, página por página, sem limite de tamanho.</p>\n        <div class=\"drop\" id=\"drop\" tabindex=\"0\" role=\"button\" aria-label=\"Selecionar arquivos do processo\">\n          <strong><span class=\"ps-step ps-inline\">1</span>Arraste os arquivos aqui ou clique para selecionar</strong>\n          <span>PDF (inclusive com mais de 1.000 páginas e digitalizado), DOCX, TXT, JPG, PNG</span>\n        </div>\n        <input type=\"file\" id=\"fin\" multiple accept=\".pdf,.docx,.txt,.jpg,.jpeg,.png\" hidden>\n        <div class=\"files\" id=\"flist\"></div>\n        <div class=\"prestart\" id=\"preStart\" aria-live=\"polite\">\n          <div class=\"ps-head\"><span class=\"ps-step\">2</span><div><b>Antes de iniciar: encarregado e destinatário</b><span class=\"ps-sub\">Obrigatório: preencha cada um ou marque a caixa “ainda não definido”. Eles entram na redação do despacho.</span></div><span class=\"ps-ok\" id=\"psOk\" hidden>✓ pronto</span></div>\n          <div id=\"preStartBody\"></div>\n          <p class=\"ps-msg\" id=\"psMsg\" hidden></p>\n        </div>\n        <div class=\"row\">\n          <button class=\"btn pri\" id=\"bStart\" disabled>Iniciar análise</button>\n          <button class=\"btn danger\" id=\"bStop\" hidden>Interromper</button>\n          <button class=\"btn\" id=\"bResume\" hidden>Retomar da etapa interrompida</button>\n          <button class=\"btn sm\" id=\"bReset\">Nova análise</button>\n        </div>\n        <p class=\"hint start-hint\" id=\"startHint\" hidden>Para habilitar o botão, conclua a etapa 2: informe o encarregado e o destinatário ou marque as caixas “ainda não definido”.</p>\n        <p class=\"hint\" id=\"engHint\"></p>\n      </div>\n\n      <div class=\"panel big\" id=\"p-proc\">\n        <h2>2 · Processamento em tempo real</h2>\n        <p class=\"lead\">Cada etapa mostra <b>o que faz</b> e, ao terminar, o seu <b>resultado</b>. Nenhuma página é descartada: o sistema confere automaticamente se cada trecho citado existe na página indicada. O tempo restante é uma estimativa que se ajusta à velocidade real do motor de IA; ao final, aparece o tempo total gasto.</p>\n        <div class=\"kpis\">\n          <div class=\"kpi\"><span class=\"kl\">Páginas lidas</span><b id=\"kPag\">0</b><small id=\"kPagS\">dos autos</small></div>\n          <div class=\"kpi\"><span class=\"kl\">Fatos extraídos</span><b id=\"kFat\">0</b><small>com página de origem</small></div>\n          <div class=\"kpi\"><span class=\"kl\">Conferência</span><b id=\"kVer\">0%</b><small>dos trechos na página citada</small></div>\n          <div class=\"kpi kpi-eta\"><span class=\"kl\" id=\"kEtaL\">Tempo restante</span><b id=\"kEta\">—</b><small id=\"kEtaS\">estimativa</small></div>\n        </div>\n        <div class=\"bar\" style=\"margin-top:12px\"><i id=\"gbar\"></i></div>\n        <p class=\"hint\" id=\"gtxt\" style=\"margin:6px 0 10px\">Aguardando o carregamento do expediente.</p>\n        <ul class=\"stages\" id=\"stages\"></ul>\n        <div id=\"errbox\"></div>\n        <details class=\"acc\" style=\"margin-top:12px\"><summary>Registro técnico do processamento</summary><div><div class=\"log\" id=\"log\"></div></div></details>\n      </div>\n    </div>\n\n    <div class=\"stack\">\n      <div class=\"panel\" id=\"p-res\">\n        <h2>3 · Resultado do juízo de admissibilidade</h2>\n        <div id=\"resEmpty\" class=\"alert info\"><b>Nenhum resultado ainda.</b>Ao final do processamento aparecem aqui a decisão sugerida, o Relatório Sintético e o Despacho Fundamentado, prontos para download.</div>\n        <div id=\"resBody\" hidden class=\"stack\">\n          <div class=\"verdict\"><div class=\"num\" id=\"vNum\">—</div><div><div class=\"lab\" id=\"vLab\">Resultado sugerido</div><div class=\"res\" id=\"vRes\"></div><div class=\"hint\" id=\"vSub\"></div></div></div>\n          <div id=\"encCard\" hidden></div>\n          <div id=\"vAlerts\"></div>\n          <div class=\"row\">\n            <div class=\"seg\" role=\"group\" aria-label=\"Documento exibido\"><button aria-pressed=\"true\" data-doc=\"rel\">Relatório sintético</button><button aria-pressed=\"false\" data-doc=\"desp\">Despacho fundamentado</button></div>\n          </div>\n          <div class=\"docprev\" id=\"docprev\"></div>\n          <div class=\"dl-grid\" id=\"dlRow\">\n            <div class=\"dl-group\"><div class=\"dl-gt\">Relatório sintético</div><div class=\"dl-btns\"><button class=\"btn dlb\" id=\"dRelPdf\" aria-label=\"Baixar o relatório em PDF\"><svg class=\"fi\" viewBox=\"0 0 32 32\" width=\"26\" height=\"26\" aria-hidden=\"true\"><path d=\"M7 2h13l7 7v19a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2z\" fill=\"#fff\" stroke=\"#c62828\" stroke-width=\"1.6\"/><path d=\"M20 2v7h7\" fill=\"#fbe1df\" stroke=\"#c62828\" stroke-width=\"1.6\" stroke-linejoin=\"round\"/><rect x=\"2\" y=\"15\" width=\"21\" height=\"10\" rx=\"2\" fill=\"#c62828\"/><text x=\"12.5\" y=\"22.6\" text-anchor=\"middle\" font-family=\"Arial,Helvetica,sans-serif\" font-size=\"7.4\" font-weight=\"700\" fill=\"#fff\">PDF</text></svg><span class=\"dlb-t\"><b>PDF</b><small>leitura e impressão</small></span></button><button class=\"btn dlb\" id=\"dRelDocx\" aria-label=\"Baixar o relatório em Word\"><svg class=\"fi\" viewBox=\"0 0 32 32\" width=\"26\" height=\"26\" aria-hidden=\"true\"><path d=\"M9 2h13l7 7v19a2 2 0 0 1-2 2H9a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2z\" fill=\"#fff\" stroke=\"#1e5bb8\" stroke-width=\"1.6\"/><path d=\"M22 2v7h7\" fill=\"#dbe7fb\" stroke=\"#1e5bb8\" stroke-width=\"1.6\" stroke-linejoin=\"round\"/><line x1=\"18\" y1=\"14\" x2=\"25\" y2=\"14\" stroke=\"#1e5bb8\" stroke-width=\"1.5\"/><line x1=\"18\" y1=\"18\" x2=\"25\" y2=\"18\" stroke=\"#1e5bb8\" stroke-width=\"1.5\"/><line x1=\"18\" y1=\"22\" x2=\"25\" y2=\"22\" stroke=\"#1e5bb8\" stroke-width=\"1.5\"/><rect x=\"2\" y=\"11\" width=\"14\" height=\"14\" rx=\"2\" fill=\"#1e5bb8\"/><text x=\"9\" y=\"21.8\" text-anchor=\"middle\" font-family=\"Arial,Helvetica,sans-serif\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\">W</text></svg><span class=\"dlb-t\"><b>Word</b><small>editável (.docx)</small></span></button></div></div>\n            <div class=\"dl-group\"><div class=\"dl-gt\">Despacho fundamentado</div><div class=\"dl-btns\"><button class=\"btn dlb\" id=\"dDespPdf\" aria-label=\"Baixar o despacho em PDF\"><svg class=\"fi\" viewBox=\"0 0 32 32\" width=\"26\" height=\"26\" aria-hidden=\"true\"><path d=\"M7 2h13l7 7v19a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2z\" fill=\"#fff\" stroke=\"#c62828\" stroke-width=\"1.6\"/><path d=\"M20 2v7h7\" fill=\"#fbe1df\" stroke=\"#c62828\" stroke-width=\"1.6\" stroke-linejoin=\"round\"/><rect x=\"2\" y=\"15\" width=\"21\" height=\"10\" rx=\"2\" fill=\"#c62828\"/><text x=\"12.5\" y=\"22.6\" text-anchor=\"middle\" font-family=\"Arial,Helvetica,sans-serif\" font-size=\"7.4\" font-weight=\"700\" fill=\"#fff\">PDF</text></svg><span class=\"dlb-t\"><b>PDF</b><small>leitura e impressão</small></span></button><button class=\"btn dlb\" id=\"dDespDocx\" aria-label=\"Baixar o despacho em Word\"><svg class=\"fi\" viewBox=\"0 0 32 32\" width=\"26\" height=\"26\" aria-hidden=\"true\"><path d=\"M9 2h13l7 7v19a2 2 0 0 1-2 2H9a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2z\" fill=\"#fff\" stroke=\"#1e5bb8\" stroke-width=\"1.6\"/><path d=\"M22 2v7h7\" fill=\"#dbe7fb\" stroke=\"#1e5bb8\" stroke-width=\"1.6\" stroke-linejoin=\"round\"/><line x1=\"18\" y1=\"14\" x2=\"25\" y2=\"14\" stroke=\"#1e5bb8\" stroke-width=\"1.5\"/><line x1=\"18\" y1=\"18\" x2=\"25\" y2=\"18\" stroke=\"#1e5bb8\" stroke-width=\"1.5\"/><line x1=\"18\" y1=\"22\" x2=\"25\" y2=\"22\" stroke=\"#1e5bb8\" stroke-width=\"1.5\"/><rect x=\"2\" y=\"11\" width=\"14\" height=\"14\" rx=\"2\" fill=\"#1e5bb8\"/><text x=\"9\" y=\"21.8\" text-anchor=\"middle\" font-family=\"Arial,Helvetica,sans-serif\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\">W</text></svg><span class=\"dlb-t\"><b>Word</b><small>editável (.docx)</small></span></button></div></div>\n          </div>\n          <div id=\"funcBox\"></div>\n          <div id=\"apensaBox\" class=\"stack\"></div>\n        </div>\n      </div>\n\n      <div class=\"panel\" id=\"p-campos\">\n        <h2>Campos do despacho</h2>\n        <p class=\"lead\">Preencha antes de baixar. Os campos com <span class=\"req\">*</span> são obrigatórios; o sistema não gera o despacho final com eles em branco. Os demais são opcionais.</p>\n        <div class=\"alert warn\" id=\"fieldsHint\" hidden style=\"margin-bottom:12px\"><b>Valores lembrados deste navegador</b><span id=\"fieldsHintTxt\"></span> <button type=\"button\" class=\"btn sm\" id=\"bClearFields\" style=\"margin-top:6px\">Limpar campos lembrados</button></div>\n        <div class=\"fgroups\" id=\"fields\"></div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ============ APRESENTAÇÃO ============ -->\n<section class=\"view\" id=\"v-apresentacao\" hidden>\n  <div class=\"panel\">\n    <div class=\"row\" style=\"justify-content:space-between\"><h2>Apresentação do sistema</h2><div class=\"row\"><button class=\"btn sm\" id=\"dApDocx\">Baixar em Word</button><button class=\"btn sm\" id=\"dApPdf\">Baixar em PDF</button></div></div>\n    <div class=\"docprev\" id=\"apres\" style=\"max-height:none\"></div>\n  </div>\n</section>\n\n<!-- ============ FLUXO ============ -->\n<section class=\"view\" id=\"v-fluxo\" hidden>\n  <div class=\"panel\">\n    <h2>Fluxo sistêmico do juízo de admissibilidade da denúncia</h2>\n    <p class=\"lead\">Arraste para mover, use a roda do mouse ou o gesto de pinça para aproximar. O botão central reenquadra o mapa.</p>\n    <div class=\"flowbox\" id=\"flow\">\n      <div class=\"tools\"><button class=\"btn\" id=\"zIn\" aria-label=\"Aproximar\">+</button><button class=\"btn\" id=\"zOut\" aria-label=\"Afastar\">−</button><button class=\"btn\" id=\"zFit\" aria-label=\"Reenquadrar\">⤢</button></div>\n      <svg id=\"fsvg\" role=\"img\" aria-label=\"Fluxograma do juízo de admissibilidade\"><g id=\"fg\"></g></svg>\n    </div>\n  </div>\n</section>\n\n<!-- ============ NORMAS ============ -->\n<section class=\"view\" id=\"v-normas\" hidden>\n  <div class=\"panel\">\n    <h2>Base normativa embarcada</h2>\n    <p class=\"lead\">É a única fonte de fundamentos que os agentes podem citar. Qualquer dispositivo citado fora desta base é bloqueado automaticamente e marcado para conferência no relatório.</p>\n    <div class=\"scroll-x\"><table class=\"normtbl\" id=\"normtbl\"></table></div>\n  </div>\n  <div class=\"panel\" id=\"legispanel\" style=\"margin-top:16px\"></div>\n  <div class=\"panel\" id=\"normgaps\" style=\"margin-top:16px\"></div>\n</section>\n\n<!-- ============ APOIO ============ -->\n<section class=\"view\" id=\"v-videos\" hidden>\n  <div class=\"panel stack\">\n    <h2>Como usar</h2>\n    <p class=\"lead\">Nesta aba estão os vídeos que ensinam a usar o JAPRO, do primeiro acesso ao apensamento. Eles foram organizados na ordem em que você vai precisar deles: se é a sua primeira vez, assista na sequência de 1 a 4.</p>\n    <div class=\"vid-info\"><b>Como assistir:</b> cada botão abre o vídeo no Google Drive, em uma nova aba, sem interromper a análise em andamento nesta página. Se o Drive pedir permissão, entre com a sua conta institucional.</div>\n    <div class=\"vid-grid\">\n      <article class=\"vid-card\">\n        <div class=\"vid-head\"><span class=\"vid-num\" aria-hidden=\"true\">1</span><h3>Como ter acesso ao sistema</h3></div>\n        <p class=\"vid-sub\">Primeiros passos, antes da primeira análise.</p>\n        <div class=\"vid-k\">O que o vídeo aborda</div>\n        <ul class=\"vid-list\"><li>onde encontrar o JAPRO e como abri-lo;</li><li>o que aparece na primeira abertura;</li><li>o que conferir antes de começar a usar.</li></ul>\n        <a class=\"btn vid-btn\" href=\"https://drive.google.com/file/d/1MCcW5l_R9MM-B6x-in6x2-RXhRylB2tj/view?usp=drive_link\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"Assistir ao vídeo 1: Como ter acesso ao sistema (abre em nova aba)\"><svg class=\"yt-ico\" viewBox=\"0 0 28 20\" width=\"28\" height=\"20\" aria-hidden=\"true\"><rect x=\"0\" y=\"0\" width=\"28\" height=\"20\" rx=\"5\" fill=\"#d32f2f\"/><path d=\"M11 5.5v9l8-4.5z\" fill=\"#fff\"/></svg><span>Como ter acesso ao sistema</span><span class=\"vid-ext\" aria-hidden=\"true\">↗</span></a>\n      </article>\n      <article class=\"vid-card\">\n        <div class=\"vid-head\"><span class=\"vid-num\" aria-hidden=\"true\">2</span><h3>Como usar o sistema</h3></div>\n        <p class=\"vid-sub\">Do carregamento dos autos ao fim do processamento.</p>\n        <div class=\"vid-k\">O que o vídeo aborda</div>\n        <ul class=\"vid-list\"><li>como anexar o processo (PDF, Word, texto ou imagem);</li><li>como preencher o encarregado, o destinatário e os campos do despacho;</li><li>como iniciar a análise e acompanhar cada etapa do processamento.</li></ul>\n        <a class=\"btn vid-btn\" href=\"https://drive.google.com/file/d/1H0cAk0sc6patzwAkwk9sMZr-E0zfmw0U/view?usp=drive_link\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"Assistir ao vídeo 2: Como usar o sistema (abre em nova aba)\"><svg class=\"yt-ico\" viewBox=\"0 0 28 20\" width=\"28\" height=\"20\" aria-hidden=\"true\"><rect x=\"0\" y=\"0\" width=\"28\" height=\"20\" rx=\"5\" fill=\"#d32f2f\"/><path d=\"M11 5.5v9l8-4.5z\" fill=\"#fff\"/></svg><span>Como usar o sistema</span><span class=\"vid-ext\" aria-hidden=\"true\">↗</span></a>\n      </article>\n      <article class=\"vid-card\">\n        <div class=\"vid-head\"><span class=\"vid-num\" aria-hidden=\"true\">3</span><h3>Analisando o resultado gerado</h3></div>\n        <p class=\"vid-sub\">Como ler, conferir e baixar o que o sistema entregou.</p>\n        <div class=\"vid-k\">O que o vídeo aborda</div>\n        <ul class=\"vid-list\"><li>a decisão sugerida, o relatório sintético e o despacho fundamentado;</li><li>os avisos «Resolva antes de assinar», «Confira» e «Ajustes automáticos»;</li><li>como aplicar uma correção sugerida e baixar o documento em PDF ou Word.</li></ul>\n        <a class=\"btn vid-btn\" href=\"https://drive.google.com/file/d/1_Md_V7qr1AHfX723w24SR7a9hzhSqegW/view?usp=drive_link\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"Assistir ao vídeo 3: Analisando o resultado gerado (abre em nova aba)\"><svg class=\"yt-ico\" viewBox=\"0 0 28 20\" width=\"28\" height=\"20\" aria-hidden=\"true\"><rect x=\"0\" y=\"0\" width=\"28\" height=\"20\" rx=\"5\" fill=\"#d32f2f\"/><path d=\"M11 5.5v9l8-4.5z\" fill=\"#fff\"/></svg><span>Analisando o resultado gerado</span><span class=\"vid-ext\" aria-hidden=\"true\">↗</span></a>\n      </article>\n      <article class=\"vid-card\">\n        <div class=\"vid-head\"><span class=\"vid-num\" aria-hidden=\"true\">4</span><h3>Apensamento</h3></div>\n        <p class=\"vid-sub\">Quando já existe procedimento instaurado sobre o mesmo fato.</p>\n        <div class=\"vid-k\">O que o vídeo aborda</div>\n        <ul class=\"vid-list\"><li>como anexar a portaria ou o procedimento existente para o cruzamento;</li><li>como interpretar o resultado do cruzamento;</li><li>quando e como forçar o apensamento, com justificativa e documento.</li></ul>\n        <a class=\"btn vid-btn\" href=\"https://drive.google.com/file/d/1IBsAwSqGz4RQaL9x8eOZ5fcDXxmd7fge/view?usp=drive_link\" target=\"_blank\" rel=\"noopener noreferrer\" aria-label=\"Assistir ao vídeo 4: Apensamento (abre em nova aba)\"><svg class=\"yt-ico\" viewBox=\"0 0 28 20\" width=\"28\" height=\"20\" aria-hidden=\"true\"><rect x=\"0\" y=\"0\" width=\"28\" height=\"20\" rx=\"5\" fill=\"#d32f2f\"/><path d=\"M11 5.5v9l8-4.5z\" fill=\"#fff\"/></svg><span>Apensamento</span><span class=\"vid-ext\" aria-hidden=\"true\">↗</span></a>\n      </article>\n    </div>\n  </div>\n</section>\n<section class=\"view\" id=\"v-apoio\" hidden>\n  <div class=\"panel stack\">\n    <h2>Outras ferramentas de apoio</h2>\n    <p class=\"lead\">Recursos da Corregedoria-Geral que complementam o JAPRO. O <b>Gemini Notebook</b> e o <b>Compêndio Normativo</b> exigem conta institucional <b>@pm.mt.gov.br</b>; o <b>Plantão</b> atende pelo WhatsApp, sem exigência de conta.</p>\n    <div class=\"apoio-grid\">\n      <article class=\"apoio-card\">\n        <div class=\"apoio-ico\" aria-hidden=\"true\"><svg viewBox=\"0 0 48 48\" width=\"40\" height=\"40\" fill=\"none\" stroke=\"var(--steel)\" stroke-width=\"2.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"24\" y1=\"5\" x2=\"24\" y2=\"11\"/><circle cx=\"24\" cy=\"4\" r=\"2\" fill=\"var(--gold)\" stroke=\"none\"/><rect x=\"9\" y=\"11\" width=\"30\" height=\"24\" rx=\"7\" fill=\"var(--surface)\"/><rect x=\"15\" y=\"18\" width=\"18\" height=\"10\" rx=\"4\" fill=\"var(--steel)\" stroke=\"none\"/><circle cx=\"20.5\" cy=\"23\" r=\"1.8\" fill=\"var(--gold)\" stroke=\"none\"/><circle cx=\"27.5\" cy=\"23\" r=\"1.8\" fill=\"var(--gold)\" stroke=\"none\"/><line x1=\"5\" y1=\"20\" x2=\"9\" y2=\"20\"/><line x1=\"39\" y1=\"20\" x2=\"43\" y2=\"20\"/><line x1=\"5\" y1=\"26\" x2=\"9\" y2=\"26\"/><line x1=\"39\" y1=\"26\" x2=\"43\" y2=\"26\"/><path d=\"M17 35v4a3 3 0 0 0 3 3h8a3 3 0 0 0 3-3v-4\"/></svg></div>\n        <h3>Gemini Notebook da Corregedoria</h3>\n        <p class=\"apoio-sub\">Assistente de consulta à base normativa da PMMT</p>\n        <div class=\"apoio-list\">\n          <div class=\"ap-item\"><span class=\"ap-k\">O que é</span><p>Um caderno do Gemini Notebook (NotebookLM, do Google) carregado com toda a base normativa da PMMT — leis, decretos, portarias, regulamentos e manuais correcionais.</p></div>\n          <div class=\"ap-item\"><span class=\"ap-k\">Como ajuda</span><p>Responde a perguntas em linguagem natural citando o trecho e o documento de origem; útil para confirmar um dispositivo antes de assinar, localizar a norma aplicável a uma situação ou comparar redações.</p></div>\n          <div class=\"ap-item\"><span class=\"ap-k\">Acesso</span><p>Entre obrigatoriamente com o e-mail institucional <b>@pm.mt.gov.br</b>. No primeiro acesso, clique em <b>Solicitar acesso</b> e peça permissão como <b>Leitor</b>; o acesso é liberado pelo administrador do caderno.</p></div>\n        </div>\n        <a class=\"btn pri apoio-btn\" href=\"https://notebook.google.com/notebook/cc7a692e-e0d6-44ad-bbc4-ea1afb282cd1\" target=\"_blank\" rel=\"noopener noreferrer\">Abrir o Gemini Notebook ↗</a>\n      </article>\n      <article class=\"apoio-card\">\n        <div class=\"apoio-ico\" aria-hidden=\"true\"><svg viewBox=\"0 0 48 48\" width=\"40\" height=\"40\" fill=\"none\" stroke=\"var(--steel)\" stroke-width=\"2.4\" stroke-linejoin=\"round\"><path d=\"M5 12a3 3 0 0 1 3-3h10l4 4h18a3 3 0 0 1 3 3v3H5z\" fill=\"var(--gold)\" stroke=\"var(--gold)\"/><path d=\"M5 19h38v17a3 3 0 0 1-3 3H8a3 3 0 0 1-3-3z\" fill=\"var(--surface)\"/><line x1=\"12\" y1=\"28\" x2=\"28\" y2=\"28\" stroke=\"var(--gold)\"/></svg></div>\n        <h3>Compêndio Normativo</h3>\n        <p class=\"apoio-sub\">Acervo em pasta compartilhada do Google Drive</p>\n        <div class=\"apoio-list\">\n          <div class=\"ap-item\"><span class=\"ap-k\">O que é</span><p>A pasta com os arquivos integrais da base normativa (PDFs das leis, decretos, portarias, regulamentos e manuais) organizados pela Corregedoria-Geral.</p></div>\n          <div class=\"ap-item\"><span class=\"ap-k\">Como ajuda</span><p>Permite abrir o texto original de qualquer norma citada no relatório ou no despacho e conferir a redação literal do dispositivo.</p></div>\n          <div class=\"ap-item\"><span class=\"ap-k\">Acesso</span><p>Com o e-mail institucional <b>@pm.mt.gov.br</b>; se a pasta pedir permissão, clique em <b>Solicitar acesso</b>.</p></div>\n        </div>\n        <a class=\"btn gold apoio-btn\" href=\"https://drive.google.com/drive/folders/11nxkZk-5oiXCby_wLx6bcDKf5tdPpenH?usp=drive_link\" target=\"_blank\" rel=\"noopener noreferrer\">Abrir o Compêndio ↗</a>\n      </article>\n      <article class=\"apoio-card\">\n        <div class=\"apoio-ico\" aria-hidden=\"true\"><svg viewBox=\"0 0 48 48\" width=\"40\" height=\"40\" fill=\"none\" stroke=\"#25D366\" stroke-width=\"2.6\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M24 8c-9.4 0-17 6.6-17 14.8 0 3.4 1.3 6.5 3.6 9L8.5 40l8.6-2.7a19 19 0 0 0 6.9 1.3c9.4 0 17-6.6 17-14.8S33.4 8 24 8z\" fill=\"#ffffff\"/><circle cx=\"17\" cy=\"23\" r=\"1.9\" fill=\"#25D366\" stroke=\"none\"/><circle cx=\"24\" cy=\"23\" r=\"1.9\" fill=\"#25D366\" stroke=\"none\"/><circle cx=\"31\" cy=\"23\" r=\"1.9\" fill=\"#25D366\" stroke=\"none\"/></svg></div>\n        <h3>Plantão da Corregedoria</h3>\n        <p class=\"apoio-sub\">Atendimento por WhatsApp a quem usa a ferramenta</p>\n        <div class=\"apoio-list\">\n          <div class=\"ap-item\"><span class=\"ap-k\">Para que serve</span><p>Tirar dúvidas sobre a utilização do JAPRO e sobre procedimentos correcionais com o plantão da Corregedoria-Geral.</p></div>\n          <div class=\"ap-item\"><span class=\"ap-k\">Como ajuda</span><p>Orientação rápida quando o resultado da análise, um alerta do relatório ou um passo do fluxo gerar dúvida antes da assinatura.</p></div>\n          <div class=\"ap-item\"><span class=\"ap-k\">Contato</span><p>WhatsApp <b>(65) 98170-0385</b>. O botão abre a conversa diretamente no aplicativo ou no WhatsApp Web.</p></div>\n        </div>\n        <a class=\"btn apoio-btn apoio-wa\" href=\"https://wa.me/5565981700385?text=Ol%C3%A1%2C%20preciso%20de%20orienta%C3%A7%C3%A3o%20sobre%20o%20novo%20sistema%20JAPRO%20%28Ju%C3%ADzo%20de%20Admissibilidade%20Processual%29%20elaborado%20pela%20Coordenadoria%20de%20Instaura%C3%A7%C3%A3o%20e%20Controle%20Processual%20%28CICP%29.\" target=\"_blank\" rel=\"noopener noreferrer\">Falar com o Plantão ↗</a>\n      </article>\n    </div>\n    <p class=\"hint\">Os três recursos abrem em nova aba e não interferem na análise em andamento nesta página.</p>\n  </div>\n</section>\n\n<!-- ============ CONFIG ============ -->\n<section class=\"view\" id=\"v-config\" hidden>\n  <div class=\"panel stack\">\n    <div><h2>Motores de inteligência artificial</h2>\n    <p class=\"lead\">Escolha o motor. As chaves ficam salvas somente neste navegador, todas ao mesmo tempo, e nunca aparecem nos documentos.</p></div>\n    <div class=\"eng\" id=\"engs\"></div>\n    <div class=\"alert info\" id=\"envInfo\"></div>\n  </div>\n</section>\n\n</div></main>\n<footer class=\"gut\" style=\"text-align:center;font-size:11.5px;color:var(--muted);padding:10px 0 calc(14px + env(safe-area-inset-bottom,0px))\">JAPRO · Corregedoria-Geral da PMMT · versão <span id=\"verTag\"></span></footer>\n<div class=\"foot gut\">JAPRO · ferramenta de apoio à decisão da Autoridade de Polícia Judiciária Militar. A decisão e a assinatura são sempre do analista e da autoridade competente.</div>\n<div id=\"modal\"></div>\n<style>\n/* A2 */\n/* etapa dispensada (não precisou rodar neste processamento): fim de etapa, com o motivo */\n.stages li.skip{opacity:.92}\n.stages li.skip .d{background:var(--surface-2);border-color:var(--muted)}\n.stages li.skip .sst{background:var(--surface-2);border-color:var(--muted);color:var(--muted)}\n.stages li.skip .sr{border-left-color:var(--muted)}\n/* tela de forçar o apensamento: passos numerados */\n.fz .lead{margin:0}\n.fz-steps{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:12px}\n.fz-step{display:flex;gap:12px;align-items:flex-start;padding:12px 14px;border:1px solid var(--line);border-radius:10px;background:var(--surface)}\n.fz-n{flex:none;width:28px;height:28px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;background:var(--steel);color:#fff;font-weight:700;font-size:14px}\n.fz-c{flex:1;min-width:0;display:flex;flex-direction:column;gap:8px}\n.fz-c h3{margin:2px 0 0;font-size:14.5px}\n.fz-c p{margin:0;line-height:1.5}\n.fz-l{margin:0;padding-left:18px;display:flex;flex-direction:column;gap:3px;line-height:1.45}\n/* dica em tópicos (mesmo visual das demais, sem fonte monoespaçada) */\n.tipbox.lst{width:320px}\n.tipbox.lst .tt{font-size:10.5px;letter-spacing:.08em;text-transform:uppercase;color:#9fb0e0;font-weight:600}\n.tipbox.lst ul{margin:0;padding-left:16px;display:flex;flex-direction:column;gap:4px;font-family:var(--f-body);font-size:12.5px;color:#eef1f7}\n.tipbox.lst .tt+ul{margin-top:-2px}\n.tipbox.lst .tt:not(:first-child){padding-top:8px;border-top:1px solid rgba(255,255,255,.14)}\n/* perguntas que mudariam a decisão (dados funcionais) */\n.lac{border:1px solid var(--line);border-radius:10px;padding:10px 12px;background:var(--surface);display:flex;flex-direction:column;gap:8px}\n.lac-h{display:flex;flex-wrap:wrap;gap:6px 10px;align-items:baseline}\n.lac-m{font-weight:700}\n.lac-d{font-size:12px;font-weight:700;letter-spacing:.04em;text-transform:uppercase;color:var(--steel)}\n.lac-l{margin:0;display:grid;grid-template-columns:minmax(120px,max-content) 1fr;gap:4px 12px;font-size:13px;line-height:1.45}\n.lac-l dt{font-weight:600;color:var(--muted)}\n.lac-l dd{margin:0}\n@media (max-width:640px){.lac-l{grid-template-columns:1fr}.lac-l dd{margin-bottom:4px}}\n</style>\n";document.body.innerHTML=H;document.title="JAPRO Corregedoria-Geral";var L=["https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js", "https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js", "https://cdnjs.cloudflare.com/ajax/libs/mammoth/1.6.0/mammoth.browser.min.js", "https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js", "https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js"];L.forEach(function(u){var s=document.createElement('script');s.src=u;document.head.appendChild(s)});})();
